<?php
declare(strict_types=1);
namespace App\Repositories; use App\Core\Database;
final class AccountRepository { public function all():array{return Database::connection()->query('SELECT a.*, COALESCE(a.current_balance,a.opening_balance) balance FROM accounts a ORDER BY a.name')->fetchAll();} public function find(int $id):?array{$s=Database::connection()->prepare('SELECT * FROM accounts WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;} public function create(array $d):int{$s=Database::connection()->prepare('INSERT INTO accounts(name,type,opening_balance,current_balance,description,status,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),NOW())');$s->execute([$d['name'],$d['type'],$d['opening_balance']??0,$d['opening_balance']??0,$d['description']??null,$d['status']??'active']);return (int)Database::connection()->lastInsertId();} public function update(int $id,array $d):void{$s=Database::connection()->prepare('UPDATE accounts SET name=?,type=?,description=?,status=?,updated_at=NOW() WHERE id=?');$s->execute([$d['name'],$d['type'],$d['description']??null,$d['status']??'active',$id]);}}
